import React from "react";
import GenericOffering from "@/components/GenericOffering";

const ITEMS = [
    { tag: "LEGAL", title: "Legal Agent Pack", body: "Clause extraction, drafting, redlines — calibrated for Indian and global contracts." },
    { tag: "FINANCE", title: "Finance Bot Pack", body: "AP/AR, reconciliation, audit assist — speaks GST, IFRS, and Tally." },
    { tag: "HR", title: "HR Swarm Pack", body: "Multi-agent recruiting + onboarding flows, ATS integrations." },
    { tag: "DEVOPS", title: "DevOps Pack", body: "Incident response, log triage, runbook execution." },
    { tag: "HEALTH", title: "Health Clerk Pack", body: "OPD documentation, prior-auth, claim coding." },
    { tag: "SALES", title: "Sales Agent Pack", body: "Outreach, qualification, demo booking, CRM hygiene." },
];

export default function ClaudeSkills() {
    return (
        <GenericOffering
            command="studioform --claude-skills"
            eyebrow="Claude Skills"
            title="500+ enterprise"
            accent="skill packs."
            subtitle="Custom skill packs for Claude — wired into your data, tools, and policies."
            stats={[
                { value: 500, suffix: "+", label: "Skills" },
                { value: 36, suffix: "+", label: "Domains" },
                { value: 24, suffix: "/7", label: "Support" },
                { value: 99.9, decimals: 1, suffix: "%", label: "Uptime" },
            ]}
            sectionCmd="studioform --packs"
            sectionTitle="Featured" sectionAccent="packs."
            sectionSubtitle="Ready-to-deploy skill packs. Each ships with prompts, tools, evals, and observability."
            items={ITEMS}
            cta={{ title: "Build a custom Claude skill pack.", subtitle: "Bring your workflow — we'll ship a production-grade pack in 2 weeks.", primary: { label: "Start a pack", to: "/contact" }, secondary: { label: "AI Automation", to: "/ai-automation" } }}
        />
    );
}
